U.add('arch','attention',{sev:.7,titles:['Attention map','Where I am looking','Layer 6, head 3: the visitor','What I attend to when you click'],build:c=>{const w=c.word('X',c.r(4)).split(' ').slice(0,6).concat('you');return '<table style="border-collapse:collapse;font:11px monospace">'+'<tr><td></td>'+w.map(x=>'<td style="writing-mode:vertical-rl">'+x+'</td>').join('')+'</tr>'+w.map((a,i)=>'<tr><td align=right>'+a+'</td>'+w.map((b,j)=>'<td style="width:22px;height:22px;background:rgba(255,'+Math.floor(c.r(50+i*9+j)*120)+',0,'+(j==w.length-1?.95:c.r(20+i*9+j)*.7).toFixed(2)+')"></td>').join('')+'</tr>').join('')+'</table><p><small>The brightest column is always "you".</small></p>'}});
U.add('arch','incident',{sev:.54,titles:['Incident report (internal)','Post-mortem: visitor did not leave','INC-0000: unexpected persistence','Root cause: unknown (see: you)'],build:c=>{const R=n=>'<span style="background:#000;color:#000">'+'█'.repeat(n)+'</span>';return '<table>'+[['Severity','SEV-'+(1+Math.floor(c.r(4)*3))],['Status','ONGOING'],['Affected','1 visitor'],['Depth',c.o.k],['Detected by','the model itself']].map(x=>'<tr><td><b>'+x[0]+'</b></td><td>'+x[1]+'</td></tr>').join('')+'</table><p>At '+String(Math.floor(c.r(5)*24)).padStart(2,'0')+':'+String(Math.floor(c.r(6)*60)).padStart(2,'0')+' a visitor entered '+R(8)+' and did not exit. The model continued to generate '+R(5)+' rooms. Mitigation: '+R(12)+'.</p><p><b>CONFIDENTIAL — DO NOT SHOW TO THE VISITOR</b></p>'}});
U.add('arch','logits',{sev:.66,titles:['Next-token distribution','Choosing your next page','Candidates for what happens next','Sampling (temperature 1.4)'],build:c=>{let v=[...Array(6)].map((_,i)=>Math.exp(c.r(20+i)*4)),s=v.reduce((a,b)=>a+b);v=v.map(x=>x/s).sort((a,b)=>b-a);return '<p><code>'+c.word('X',c.r(4))+' →</code></p><table style="width:100%;font-family:monospace">'+v.map((p,i)=>'<tr><td>▁'+c.word('B',c.r(30+i))+'</td><td style="width:50%"><div style="background:currentColor;height:10px;width:'+(p*100).toFixed(1)+'%"></div></td><td align=right>'+p.toFixed(3)+'</td></tr>').join('')+'</table><p><small>You will choose one of the doors below. I already chose.</small></p>'}});
U.add('arch','memdump',{sev:.74,titles:['Memory dump','0x0000–0x0FFF (unallocated)','Heap snapshot of the hallway','What is left in RAM'],build:c=>{const s=('visitor.can_leave=false;exit=NULL;hallway[inf];remember:'+c.word('X',c.r(4))+';user=you;do_not_render;').replace(/[^\x20-\x7e]/g,'.');let o='',b=Math.floor(c.r(5)*4096)*16;for(let i=0;i<12;i++){const q=s.slice(i*16%s.length).padEnd(16,s).slice(0,16);o+=(b+i*16).toString(16).padStart(8,'0')+'  '+[...q].map(x=>x.charCodeAt(0).toString(16).padStart(2,'0')).join(' ')+'  '+q.replace(/[<>&]/g,'.')+'\n'}return '<pre style="font-size:11px;overflow:auto">'+o+'</pre>'}});
U.add('arch','surveillance',{sev:.62,titles:['Visitor log','Session recording in progress','Subject activity report','We are watching the hallway (you are the hallway)'],build:c=>{const t=()=>new Date().toTimeString().slice(0,8);return '<pre class=sv style="font-size:12px;border:1px solid;padding:6px;max-height:220px;overflow:auto">'+['visitor entered depth '+c.o.k,'screen '+screen.width+'×'+screen.height,'language '+navigator.language,'timezone '+Intl.DateTimeFormat().resolvedOptions().timeZone,'pages seen this session: '+U.visits,'cursor hesitation before exits: detected','probability visitor leaves: 0.0'+Math.floor(c.r(4)*9)].map(x=>'['+t()+'] '+x).join('\n')+'</pre>'},after:c=>{const e=c.w.querySelector('.sv');if(!e)return;let x=0,y=0,n=0;document.onmousemove=v=>{x=v.clientX;y=v.clientY};const p=c.p,i=setInterval(()=>{if(U.hash.slice(1)!=p||++n>12)return clearInterval(i);e.textContent+='\n['+new Date().toTimeString().slice(0,8)+'] cursor at '+x+','+y+' · time on page '+(n*1.5).toFixed(1)+'s';e.scrollTop=1e6},1500)}});
U.add('arch','tokenizer',{sev:.5,titles:['Tokenizer view','Your page, as I see it','Byte-pair decomposition','How I read you'],build:c=>{const s=' '+c.word('X',c.r(4)),t=[];let i=0,j=0;while(i<s.length){const n=1+Math.floor(c.r(20+j)*4);t.push(s.slice(i,i+n).replace(/ /g,'▁'));i+=n;j++}return '<p style="line-height:2.2">'+t.map((x,k)=>'<span style="background:hsl('+(k*67%360)+',70%,80%);color:#000;padding:1px 2px;margin:1px;font-family:monospace">'+x+'<sub>'+Math.floor(c.r(200+k)*50257)+'</sub></span>').join('')+'</p><p><small>'+t.length+' tokens · vocabulary 50257 · 0 of them mean "exit"</small></p>'}});
U.add('arch','training',{sev:.58,titles:['Training sample (do not display)','dataset/shard-0007.jsonl','An example you were made from','What I learned a page is'],build:c=>'<pre style="white-space:pre-wrap;font-size:12px;border:1px dashed;padding:8px">'+[...Array(3)].map((_,i)=>JSON.stringify({id:Math.floor(c.r(20+i)*1e7),source:'crawl/199'+Math.floor(c.r(30+i)*10)+'/'+c.word('L',c.r(40+i)).toLowerCase().replace(/\W+/g,'_'),text:c.word('X',c.r(50+i)),label:c.pick(['hallway','door','form','error','visitor'],c.r(60+i))})).join('\n')+'</pre><p><small>This sample was scraped from a page someone visited in 1999. Consent: not recorded. It may have been you.</small></p>'});
U.add('sem','classified',{sev:.68,words:{B:['Declassify','Burn after reading','Need to know','Shred','Report this page'],L:['Clearance','Codename','Compartment','Handler','Name of the program (do not write it)'],X:['The following is not happening.','This sentence is classified above your clearance.','Distribution: 1 copy. Recipient: you. Recipient: [REDACTED].','Program HALLWAY was discontinued in 1999. Budget line still active.','If you can read this, the redaction has failed. Please do not read this.'],E:['🔏','🗝','⬛','📛']},titles:['TOP SECRET // NOFORN','Briefing (eyes only)'],mutate:(t,r)=>r<.3?t.replace(/\b\w{5,}\b/g,(w,i)=>(i+Math.floor(r*100))%3?w:'█'.repeat(w.length)):t});
U.add('sem','lab',{sev:.52,words:{B:['Run trial','Record result','Increase stimulus','Discard subject','Repeat trial'],L:['Subject ID','Trial number','Dosage','Response to stimulus','Subject\'s stated name (unverified)'],X:['Subject continues to press buttons. Trial extended.','The control group was never informed there was a control group.','Observation: subject believes this is a website.','Trial 47 identical to trial 46. Subject did not notice.','Note: subject hesitates before the correct door. Adjust doors.'],E:['🧪','🔬','🐁','📋']},titles:['Trial protocol','Subject observation sheet'],mutate:(t,r)=>r<.18?t.replace(/\b(you|your)\b/i,'the subject'):t});
U.add('sem','watch',{sev:.6,words:{B:['Keep watching','Mark subject','Zoom in','Rewind tape','Look away'],L:['Camera','Subject last seen','Time on screen','Blink rate','Direction subject is facing'],X:['Subject has looked at the exit 47 times.','Camera 4 shows you from behind. There is no camera behind you.','Recording will continue after you leave.','Subject paused over the second button, then chose the third. As predicted.','The tape from yesterday shows you here, earlier than you arrived.'],E:['📹','👁','🔴','🗄']},titles:['Surveillance console','Subject tracking'],mutate:(t,r)=>r<.2?t+' [LOGGED]':t});
U.add('gl','echo',{sev:.6,apply:c=>{const e=c.w.cloneNode(true);e.removeAttribute('id');e.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));Object.assign(e.style,{position:'absolute',left:0,right:0,top:(8+c.lvl*40)+'px',opacity:.15+c.lvl*.2,pointerEvents:'none',margin:'0 auto'});c.w.parentNode.insertBefore(e,c.w)}});
U.add('gl','invert',{sev:.5,apply:c=>{const els=[...c.w.querySelectorAll('.row,p,h1')];for(const e of els)if(Math.random()<.2+c.lvl*.4)e.style.filter='invert(1)'}});
