U.add('gl','prob',{sev:.68,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())t.push(w.currentNode);t.forEach(n=>n.textContent=n.textContent.replace(/[A-Za-z]{3,}/g,x=>Math.random()<.03+c.lvl*.08?x+' (p='+Math.random().toFixed(2)+')':x))}});
U.add('gl','tokens',{sev:.54,apply:c=>{const w=document.createTreeWalker(c.w,4),t=[];while(w.nextNode())t.push(w.currentNode);t.forEach(n=>{if(Math.random()<.3+c.lvl*.5)n.textContent=n.textContent.replace(/ (?=\S)/g,' ▁').replace(/([A-Za-z]{3})(?=[A-Za-z])/g,(x)=>Math.random()<.5?x+'|':x)})}});
U.add('snd','data',{sev:.6,play:(a,o,r)=>{const lo=200+r(300)*800,sp=1000+r(301)*3000,ty=r(302)<.5?'square':'sawtooth',pr=.3+r(303)*.5,dur=.01+r(304)*.03,f=a.createBiquadFilter();f.type='lowpass';f.frequency.value=1500+r(305)*3000;f.connect(o);const t=setInterval(()=>{if(Math.random()>pr)return;const x=a.createOscillator(),g=a.createGain(),s=a.currentTime;x.type=ty;x.frequency.value=lo+Math.random()*sp;g.gain.setValueAtTime(.06,s);g.gain.setValueAtTime(0,s+dur);x.connect(g).connect(f);x.start(s);x.stop(s+dur+.01)},20+r(306)*40);return()=>clearInterval(t)}});
U.add('snd','numbers',{sev:.52,play:(a,o,r)=>{const b=500+r(300)*600,N=[1,1.19+r(301)*.1,1.5],ty=r(302)<.6?'sine':'square',f=a.createBiquadFilter(),glen=3+Math.floor(r(303)*5),dur=.08+r(304)*.12;f.type='lowpass';f.frequency.value=1200+r(305)*1300;f.connect(o);const n=a.createBufferSource(),bf=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=bf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;n.buffer=bf;n.loop=true;const bp=a.createBiquadFilter(),ng=a.createGain();bp.type='bandpass';bp.frequency.value=1000;ng.gain.value=.03;n.connect(bp).connect(ng).connect(o);n.start();let k=0;const t=setInterval(()=>{if(k++%(glen+3)>=glen)return;const x=a.createOscillator(),g=a.createGain(),s=a.currentTime;x.type=ty;x.frequency.value=b*N[Math.floor(Math.random()*3)];g.gain.setValueAtTime(ty=='sine'?.1:.05,s);g.gain.setValueAtTime(0,s+dur);x.connect(g).connect(f);x.start(s);x.stop(s+dur+.02)},250+r(306)*250);return()=>{clearInterval(t);n.stop()}}});
U.add('snd','subbass',{sev:.68,play:(a,o,r)=>{const f1=28+r(300)*12,m=a.createGain(),l=a.createOscillator(),lg=a.createGain(),lp=a.createBiquadFilter();m.gain.value=.7;l.frequency.value=.03+r(302)*.12;lg.gain.value=.3;l.connect(lg).connect(m.gain);lp.type='lowpass';lp.frequency.value=80+r(303)*80;lp.connect(m).connect(o);const s=[[f1,.26,'sine'],[f1+.5+r(301)*3.5,.2,'sine'],[f1*2,.05,r(304)<.5?'triangle':'sine']].map(([fr,gv,ty])=>{const x=a.createOscillator(),g=a.createGain();x.type=ty;x.frequency.value=fr;g.gain.value=gv;x.connect(g).connect(lp);x.start();return x});l.start();return()=>{s.forEach(x=>x.stop());l.stop()}}});